// English source-of-truth catalog. Every key here is a user-facing UI string
// that gets translated into the 6 other supported languages. The `context`
// field is for translators — it tells them WHERE the string appears and what
// it means semantically, so translations don't go literal-but-wrong (e.g.
// "Plan" the noun for a reading plan vs. "Plan" the verb).
//
// This file is the only place English source is authored. The 6 translations
// live in `strings.ts` (which is the runtime lookup table). Keep keys stable —
// changing a key invalidates the translation in every language.
//
// Naming convention: `<area>.<screen-or-component>.<purpose>` in lowerCamel.

export interface CatalogEntry {
  /** English source text — never translated. */
  en: string;
  /** Note to translators about WHERE this appears + semantic intent. */
  context: string;
}

