  'notif.confirm.title':           { en: 'Reminder set ✓', context: 'Title of the immediate confirmation notification fired the moment a user turns a reminder toggle ON — so they see proof it works (the real daily reminder only fires at the scheduled time).' },
  'notif.confirm.body':            { en: 'All set — we’ll remind you each day at {time}.', context: 'Body of the immediate confirmation notification. {time} is the scheduled HH:MM, e.g. 08:00.' },

  'notif.reliability.title': { en: "Reminders arriving late or not at all?", context: 'Title of the OEM background-restriction helper card on the Notifications screen (Android). Shown because Samsung/Xiaomi/Huawei/OPPO/vivo background limits can delay or drop scheduled reminders.' },
  'notif.reliability.body': { en: "Some phones (Samsung, Xiaomi, Huawei, OPPO, vivo and others) limit apps running in the background, which can delay or silence your reminders. Allow Her Bible to run without restrictions so they arrive on time.", context: 'Body of the reliability helper card - explains background limits and asks the user to allow the app to run unrestricted.' },
  'notif.reliability.cta': { en: "Open battery settings", context: 'Button on the reliability card - opens the battery-optimization settings list.' },

