  // ─── Help Center FAQ — answers ───────────────────────────────────────────
  'help.a.gettingStarted.p1':      { en: "Open the Prayer tab and tap Start Prayer. You'll move through a verse, a short meditation, an action step, and a guided prayer. Tap AMEN at the end to mark it complete.", context: 'FAQ answer paragraph. "AMEN" is liturgical — never translate as "agree".' },
  'help.a.gettingStarted.p2':      { en: "Morning prayer opens before 6 PM, evening prayer after 6 PM. Once both are done you'll see today's flame light up on your streak.", context: 'FAQ answer paragraph.' },
  'help.a.notesAndBookmarks.p1':   { en: 'Everything saved while reading lives under Profile → My Notes. Tap any of the three tiles to see the full list:', context: 'FAQ answer intro. The arrow "→" is a UI breadcrumb — preserve.' },
  'help.a.notesAndBookmarks.b1':   { en: 'Notes — open a verse, tap Notes, write a reflection.', context: 'FAQ answer bullet.' },
  'help.a.notesAndBookmarks.b2':   { en: 'Bookmarks — tap the bookmark icon in the chapter header.', context: 'FAQ answer bullet.' },
  'help.a.notesAndBookmarks.b3':   { en: 'Highlights — tap a verse and pick a colour dot.', context: 'FAQ answer bullet.' },
  'help.a.notesAndBookmarks.p2':   { en: 'Tap any saved bookmark or highlight to jump straight back to that verse in the Bible tab.', context: 'FAQ answer paragraph.' },
  'help.a.shareVerse.p1':          { en: 'While reading, tap a verse to open its tool bar, then tap Share. Pick one of three templates (Square, Portrait, or Story), then choose Facebook, WhatsApp, or Instagram.', context: 'FAQ answer paragraph. App names (Facebook/WhatsApp/Instagram) are brand names — do not translate.' },
  'help.a.shareVerse.p2':          { en: 'We render the image on the spot in your local language and hand it to the chosen app.', context: 'FAQ answer paragraph.' },
  'help.a.removeAds.p1':           { en: 'Go to Profile → Remove Ads. Three plans are available, all priced in your local currency by Google Play:', context: 'FAQ answer intro.' },
  'help.a.removeAds.b1':           { en: 'Lifetime — one-time purchase, never charged again.', context: 'FAQ answer bullet about the lifetime plan.' },
  'help.a.removeAds.b2':           { en: 'Annual — auto-renewing yearly subscription.', context: 'FAQ answer bullet.' },
  'help.a.removeAds.b3':           { en: 'Monthly — auto-renewing monthly subscription.', context: 'FAQ answer bullet.' },
  'help.a.removeAds.h2':           { en: 'Ads still showing after I paid?', context: 'FAQ answer sub-heading for the restore-purchase scenario.' },
  'help.a.removeAds.p2':           { en: "Open the same Remove Ads screen and tap Restore. Make sure you're signed into the Google account that made the purchase. Sync usually completes within a minute.", context: 'FAQ answer paragraph about restore.' },
  'help.a.cancelSubscription.p1':  { en: 'Subscriptions are managed by Google Play, not the app. Open Play Store → tap your profile picture → Payments & subscriptions → Subscriptions, then pick Her Bible and choose Cancel.', context: 'FAQ answer paragraph. "Google Play"/"Play Store" are brand names — keep.' },
  'help.a.cancelSubscription.p2':  { en: "You'll keep ad-free access until the current billing period ends.", context: 'FAQ answer paragraph.' },
  'help.a.switchVersion.p1':       { en: 'Open Profile → Account → Bible versions. Pick a translation and download it once; afterwards you can read it fully offline. Only fully-downloaded versions can be set as your active translation.', context: 'FAQ answer paragraph.' },
  'help.a.reminderSettings.p1':    { en: "After finishing a prayer the reminder sheet appears — tap Set Time and pick the hour you'd like to be reminded each day.", context: 'FAQ answer paragraph.' },
  'help.a.reminderSettings.p2':    { en: "You can change the time or silence reminders any time from your phone's system Settings → Notifications → Her Bible.", context: 'FAQ answer paragraph. "Her Bible" is brand.' },

